#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::panic
)]
//! Replays the actual-Node corpus (`fixtures/node-routing-default.v1.json`, generated by
//! `oracle.cjs` from the pinned core workspace store): every case must answer what Node answers.
use serde_json::Value;
use server_routing_default::{Root, Routing};
use std::sync::atomic::AtomicBool;

fn decode_hex(s: &str) -> Vec<u8> {
    s.as_bytes()
        .chunks(2)
        .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap(), 16).unwrap())
        .collect()
}

fn bytes_of(file: &Value) -> Vec<u8> {
    if let Some(text) = file["text"].as_str() {
        text.as_bytes().to_vec()
    } else {
        decode_hex(file["hex"].as_str().unwrap())
    }
}

#[test]
fn actual_node_routing_default_matrix() {
    let text = std::env::var("NOEVIA_ROUTING_DEFAULT_FIXTURE")
        .map(|p| std::fs::read_to_string(p).unwrap())
        .unwrap_or_else(|_| include_str!("fixtures/node-routing-default.v1.json").into());
    let fixture: Value = serde_json::from_str(&text).unwrap();
    // The corpus must come from the pinned core (contracts/http/core.ref), never another checkout.
    assert_eq!(
        fixture["core"],
        include_str!("../../../contracts/http/core.ref").trim()
    );
    let cases = fixture["cases"].as_array().unwrap();
    assert!(cases.len() >= 30, "corpus shrank to {}", cases.len());
    let cancel = AtomicBool::new(false);
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let dir = tempfile::tempdir().unwrap();
        let tenant = case["tenant"].as_str().unwrap();
        if !case["file"].is_null() {
            let tenant_dir = dir.path().join("users").join(tenant);
            std::fs::create_dir_all(&tenant_dir).unwrap();
            std::fs::write(tenant_dir.join("preferences.json"), bytes_of(&case["file"])).unwrap();
        }
        let root = Root::open(dir.path()).unwrap();
        let query = case["query"].as_str().unwrap_or(tenant);
        let got = root.read(query, &cancel).unwrap();
        let want = match case["expected"]["routing"].as_str().unwrap() {
            "manual" => Routing::Manual,
            "auto" => Routing::Auto,
            other => panic!("{name}: unknown expectation {other}"),
        };
        assert_eq!(got, want, "{name}");
    }
}
